-- Generee depuis sys.foreign_keys ; ne pas modifier a la main.
CREATE VIEW dbo.v_arrete_travail AS
SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'arrete_mission' AS NVARCHAR (128)) AS travail FROM [dbo].[arrete_mission] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'attestation' AS NVARCHAR (128)) AS travail FROM [dbo].[attestation] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'conclusion_cycle' AS NVARCHAR (128)) AS travail FROM [dbo].[conclusion_cycle] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'conclusion_ratio' AS NVARCHAR (128)) AS travail FROM [dbo].[conclusion_ratio] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'conclusion_revue' AS NVARCHAR (128)) AS travail FROM [dbo].[conclusion_revue] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'cours_titre' AS NVARCHAR (128)) AS travail FROM [dbo].[cours_titre] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'demande_reevaluation' AS NVARCHAR (128)) AS travail FROM [dbo].[demande_reevaluation] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'derogation' AS NVARCHAR (128)) AS travail FROM [dbo].[derogation] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite_mere] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'detention' AS NVARCHAR (128)) AS travail FROM [dbo].[detention] WHERE [entite_mere] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'dip' AS NVARCHAR (128)) AS travail FROM [dbo].[dip] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'document_produit' AS NVARCHAR (128)) AS travail FROM [dbo].[document_produit] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'dossier_verrou' AS NVARCHAR (128)) AS travail FROM [dbo].[dossier_verrou] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'ecriture_brouillon' AS NVARCHAR (128)) AS travail FROM [dbo].[ecriture_brouillon] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'evaluation_actif' AS NVARCHAR (128)) AS travail FROM [dbo].[evaluation_actif] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'export_fec' AS NVARCHAR (128)) AS travail FROM [dbo].[export_fec] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'feuille_travail' AS NVARCHAR (128)) AS travail FROM [dbo].[feuille_travail] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'import_fec' AS NVARCHAR (128)) AS travail FROM [dbo].[import_fec] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'intention_ecriture' AS NVARCHAR (128)) AS travail FROM [dbo].[intention_ecriture] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'lot_ecritures' AS NVARCHAR (128)) AS travail FROM [dbo].[lot_ecritures] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete_conclu] AS VARCHAR (20)) AS arrete, CAST(N'maintien_mission' AS NVARCHAR (128)) AS travail FROM [dbo].[maintien_mission] WHERE [entite] IS NOT NULL AND [arrete_conclu] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'mouvement_actif' AS NVARCHAR (128)) AS travail FROM [dbo].[mouvement_actif] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'od_reimport' AS NVARCHAR (128)) AS travail FROM [dbo].[od_reimport] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'od_retrait' AS NVARCHAR (128)) AS travail FROM [dbo].[od_retrait] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'parts_en_circulation' AS NVARCHAR (128)) AS travail FROM [dbo].[parts_en_circulation] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'piece_rattachement' AS NVARCHAR (128)) AS travail FROM [dbo].[piece_rattachement] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'programme_travail' AS NVARCHAR (128)) AS travail FROM [dbo].[programme_travail] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'publication_client' AS NVARCHAR (128)) AS travail FROM [dbo].[publication_client] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'publication_vl' AS NVARCHAR (128)) AS travail FROM [dbo].[publication_vl] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'rapport_annuel' AS NVARCHAR (128)) AS travail FROM [dbo].[rapport_annuel] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'ref_croisee' AS NVARCHAR (128)) AS travail FROM [dbo].[ref_croisee] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'revision_compte_courant' AS NVARCHAR (128)) AS travail FROM [dbo].[revision_compte_courant] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'saisie_annexe' AS NVARCHAR (128)) AS travail FROM [dbo].[saisie_annexe] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'synthese_proposee' AS NVARCHAR (128)) AS travail FROM [dbo].[synthese_proposee] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'valeur_instrument' AS NVARCHAR (128)) AS travail FROM [dbo].[valeur_instrument] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT CAST([entite] AS VARCHAR (20)) AS entite, CAST([arrete] AS VARCHAR (20)) AS arrete, CAST(N'visa' AS NVARCHAR (128)) AS travail FROM [dbo].[visa] WHERE [entite] IS NOT NULL AND [arrete] IS NOT NULL
UNION ALL SELECT a.entite_detentrice, CONVERT(VARCHAR (10), x.date_valeur, 23), CAST(N'expertise' AS NVARCHAR (128)) FROM dbo.expertise x JOIN dbo.actif a ON a.code = x.code_actif WHERE a.entite_detentrice IS NOT NULL AND x.date_valeur IS NOT NULL
-- l'expertise d'un actif d'une filiale a l'arrete, comme pr_arrete_porte_travail
UNION ALL SELECT r.entite, r.arrete, CAST(N'expertise' AS NVARCHAR (128)) FROM dbo.ref_arrete r CROSS APPLY dbo.fn_filiales_a_l_arrete(r.entite, r.arrete) f JOIN dbo.actif a ON a.entite_detentrice = f.entite_fille JOIN dbo.expertise x ON x.code_actif = a.code AND x.date_valeur = TRY_CAST(r.arrete AS DATE);

GO

